function SettingsPage({ctx}:{ctx:Ctx}){const [cfg,setCfg]=useState<Settings|null>(null);useEffect(()=>{api('/api/settings').then(d=>setCfg(d.settings)).catch(()=>{});},[]);if(!cfg)return null;return <section className="panel settings-panel"><h2>Original downloads only</h2><div className="notice">Image editing is disabled. Source bytes, resolution and format stay unchanged. No background removal, crop, resize, sharpening, denoising, AI upscaling or conversion.</div><p>Filename: &lt;item_code&gt;_&lt;sequence&gt;.&lt;original extension&gt;</p><p>Five genuine views per product. Full front and back required; nutrition/FSSAI details when available.</p><h2>Matching</h2><div className="form-grid">{(['highThreshold','mediumThreshold'] as const).map(k=><label key={k}>{human(k)}<input type="number" step="0.01" value={cfg[k]} onChange={e=>setCfg({...cfg,[k]:Number(e.target.value)})}/></label>)}</div><label className="check-label"><input type="checkbox" checked={cfg.watchBrowser} onChange={e=>setCfg({...cfg,watchBrowser:e.target.checked})}/>Watch permitted browser extraction</label><p className="hint">Codex visual checks and OCR read the original images without changing them. Hard mismatches remain excluded from HIGH.</p><button className="primary" onClick={()=>void ctx.run(()=>api('/api/settings','PATCH',{...cfg,downloadOnly:true,removeBackground:false,aiUpscale:false,denoise:false,sharpen:false,upscale:false}),'Download-only settings saved')}>Save settings</button></section>;}
